// Combine unpaid bills from all 5 Xero organisations that are already overdue
const ORG_SOURCES = [
  { node: 'Hinkley Homes Management', label: 'Hinkley Homes Management' },
  { node: 'Lettings', label: 'Lettings' },
  { node: 'Hinkley Homes Stays Ltd', label: 'Hinkley Homes Stays Ltd' },
  { node: 'Hinkley Homes Ltd', label: 'Hinkley Homes Ltd' },
  { node: 'Hinkley Homes Holdings', label: 'Hinkley Homes Holdings' }
];

const today = new Date(); 
today.setUTCHours(0, 0, 0, 0);
const out = [];

for (const src of ORG_SOURCES) {
  for (const it of $(src.node).all()) {
    const bill = it.json || {};
    if (Object.keys(bill).length === 0) continue;
    if (bill.Type !== 'ACCPAY' && bill.Type !== 'ACCREC') continue;
    const isReceivable = bill.Type === 'ACCREC';
    const invoiceType = isReceivable ? 'Accounts Receivable' : 'Accounts Payable';

    const amountDue = parseFloat(bill.AmountDue != null ? bill.AmountDue : (bill.Total || 0));
    if (!(amountDue > 0)) continue;

    const dueRaw = bill.DueDateString || bill.DueDate || '';
    const msMatch = String(dueRaw).match(/Date\((\d+)/);
    const dueDate = msMatch ? new Date(parseInt(msMatch[1], 10)) : new Date(dueRaw);
    if (isNaN(dueDate.getTime())) continue;

    const daysToDue = Math.floor((Date.UTC(dueDate.getUTCFullYear(), dueDate.getUTCMonth(), dueDate.getUTCDate()) - today.getTime()) / 86400000);
    if (daysToDue >= 0) continue; // overdue only

    const overdueDays = Math.abs(daysToDue);
    const dueDateText = dueDate.toISOString().slice(0, 10);
    const supplier = bill.Contact && bill.Contact.Name ? bill.Contact.Name : 'Unknown Contact';
    const invoiceNumber = bill.InvoiceNumber || bill.Reference || bill.InvoiceID || 'N/A';
    const currency = bill.CurrencyCode || 'GBP';
    const link = isReceivable
      ? 'https://go.xero.com/AccountsReceivable/View.aspx?InvoiceID=' + bill.InvoiceID
      : 'https://go.xero.com/AccountsPayable/View.aspx?invoiceID=' + bill.InvoiceID;

    // Formatting currency symbol
    const currencySymbol = currency === 'GBP' ? '£' : currency + ' ';
    const formattedAmount = currencySymbol + amountDue.toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    out.push({
      json: {
        company: src.label,
        invoiceId: bill.InvoiceID,
        invoiceType,
        invoiceTypeCode: bill.Type,
        supplier,
        invoiceNumber,
        dueDate: dueDateText,
        daysToDue,
        overdueDays,
        amountDueRaw: amountDue,
        amountDue: formattedAmount,
        amountPaid: parseFloat(bill.AmountPaid || 0) || 0,
        contactId: bill.Contact && bill.Contact.ContactID ? bill.Contact.ContactID : supplier,
        currency,
        xeroInvoiceUrl: link
      }
    });
  }
}

// Sort most overdue first
out.sort((x, y) => x.json.daysToDue - y.json.daysToDue);
return out;

// Categorises every overdue item by VALUE, AGE and RISK, assigns a priority,
// and builds one HTML email (tables) that puts the greatest financial impact first.
// Only items NOT reported before (or that became more urgent since) are emailed. Nothing new = no email.
// ---- Tweak these thresholds to suit the business ----
const VALUE_HIGH = 2500;   // GBP and above = High value
const VALUE_MEDIUM = 500;  // GBP and above = Medium value, below = Low
const EXPOSURE_HIGH = 10000; // total owed by one contact
const EXPOSURE_MEDIUM = 2500;
// Age buckets with an indicative chance the money is never collected
const AGE_BUCKETS = [
  { max: 30, label: '1-30 days', points: 0, lossRate: 0.05 },
  { max: 60, label: '31-60 days', points: 1, lossRate: 0.10 },
  { max: 90, label: '61-90 days', points: 2, lossRate: 0.25 },
  { max: 180, label: '91-180 days', points: 3, lossRate: 0.50 },
  { max: 365, label: '181-365 days', points: 4, lossRate: 0.75 },
  { max: Infinity, label: 'Over 1 year', points: 5, lossRate: 0.90 }
];
// 0 = never send the full list; 1 = Monday ... 7 = Sunday: also send everything once a week
const FULL_DIGEST_WEEKDAY = 0;
// Re-notify about invoices that are STILL overdue and unsettled every N days (0 = never repeat). Uses the saved record, no re-analysis.
const REPEAT_EVERY_DAYS = 7;
const NL = String.fromCharCode(10);
const gbp = n => '£' + Number(n || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

const items = $input.all().map(i => i.json).filter(j => j && Object.keys(j).length > 0 && j.amountDueRaw > 0);

// Exposure per contact (same company + ledger + contact)
const byContact = {};
for (const j of items) {
  const k = j.company + '|' + j.invoiceTypeCode + '|' + j.contactId;
  if (!byContact[k]) byContact[k] = { count: 0, total: 0, company: j.company, contact: j.supplier, type: j.invoiceTypeCode };
  byContact[k].count += 1;
  byContact[k].total += j.amountDueRaw;
}

const ranked = items.map(j => {
  const c = byContact[j.company + '|' + j.invoiceTypeCode + '|' + j.contactId];
  const age = AGE_BUCKETS.find(b => j.overdueDays <= b.max);
  const value = j.amountDueRaw >= VALUE_HIGH ? 'High' : j.amountDueRaw >= VALUE_MEDIUM ? 'Medium' : 'Low';
  let score = age.points;
  const reasons = [];
  if (age.points >= 2) reasons.push(age.label + ' overdue');
  if (c.count >= 3) { score += 2; reasons.push(c.count + ' overdue items for this contact'); }
  else if (c.count === 2) { score += 1; reasons.push('2 overdue items for this contact'); }
  if (c.total >= EXPOSURE_HIGH) { score += 2; reasons.push(gbp(c.total) + ' total outstanding with contact'); }
  else if (c.total >= EXPOSURE_MEDIUM) { score += 1; reasons.push(gbp(c.total) + ' total outstanding with contact'); }
  if (j.amountPaid > 0) { score -= 1; reasons.push('part-paid (engaging)'); }
  const risk = score >= 5 ? 'High' : score >= 2 ? 'Medium' : 'Low';
  let priority = 3;
  if ((value === 'High' && risk !== 'Low') || (value === 'Medium' && risk === 'High')) priority = 1;
  else if ((value === 'High') || (value === 'Medium' && risk === 'Medium') || (value === 'Low' && risk === 'High')) priority = 2;
  const valueAtRisk = Math.round(j.amountDueRaw * age.lossRate * 100) / 100;
  return Object.assign({}, j, { valueBand: value, ageBucket: age.label, riskScore: score, riskProfile: risk, riskReasons: reasons, priority, valueAtRisk, contactExposure: c.total, contactOverdueCount: c.count });
});

ranked.sort((a, b) => a.priority - b.priority || b.valueAtRisk - a.valueAtRisk || b.amountDueRaw - a.amountDueRaw);


// ---- what has already been reported (data table "Overdue Reported") ----
const reported = {};
const lastSeen = {}, firstSeen = {};
try {
  for (const r of $('Get reported overdue').all()) {
    const j = r.json || {};
    if (!j.invoice_key) continue;
    const p = Number(j.priority) || 3;
    reported[j.invoice_key] = reported[j.invoice_key] === undefined ? p : Math.min(reported[j.invoice_key], p);
    const t = Date.parse(j.reported_at) || 0;
    if (!(lastSeen[j.invoice_key] >= t)) lastSeen[j.invoice_key] = t;
    if (t && !(firstSeen[j.invoice_key] <= t)) firstSeen[j.invoice_key] = t;
  }
} catch (e) { /* no history available: everything counts as new */ }
for (const r of ranked) {
  const key = r.company + '|' + (r.invoiceId || r.invoiceNumber);
  r.invoiceKey = key;
  if (firstSeen[key]) r.firstReported = new Date(firstSeen[key]).toISOString().slice(0, 10);
  if (reported[key] === undefined) r.change = 'new';
  else if (r.priority < reported[key]) r.change = 'escalated';
  else if (REPEAT_EVERY_DAYS > 0 && lastSeen[key] && (Date.now() - lastSeen[key]) >= REPEAT_EVERY_DAYS * 86400000 - 3600000) r.change = 'reminder';
  else r.change = '';
}
const fullDay = FULL_DIGEST_WEEKDAY > 0 && $now.setZone('Europe/London').weekday === FULL_DIGEST_WEEKDAY;
const all = ranked;
const fresh = ranked.filter(r => r.change);
if (!fresh.length && !fullDay) return [];
const shown = fullDay ? all : fresh;
const rec = all.filter(r => r.invoiceTypeCode === 'ACCREC');
const pay = all.filter(r => r.invoiceTypeCode === 'ACCPAY');
const sum = (arr, f) => arr.reduce((t, r) => t + (r[f] || 0), 0);
const esc = v => String(v === null || v === undefined ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

// ---------- HTML email (inline styles so it renders in Gmail and Outlook) ----------
const F = 'font-family:Arial,Helvetica,sans-serif;';
const TABLE = 'border-collapse:collapse;width:100%;' + F + 'font-size:13px;';
const TH = 'background:#f2f4f7;color:#344054;text-align:left;padding:8px 10px;border:1px solid #d0d5dd;white-space:nowrap;';
const TD = 'padding:8px 10px;border:1px solid #e4e7ec;vertical-align:top;color:#101828;';
const TDR = TD + 'text-align:right;white-space:nowrap;';
const H2 = F + 'font-size:15px;color:#101828;margin:24px 0 8px;';
const pill = (txt, bg, fg) => '<span style="display:inline-block;padding:2px 8px;border-radius:10px;font-size:12px;background:' + bg + ';color:' + fg + ';">' + esc(txt) + '</span>';
const RISK = { High: ['#fee4e2', '#b42318'], Medium: ['#fef0c7', '#b54708'], Low: ['#dcfae6', '#067647'] };
const riskPill = r => pill(r, RISK[r][0], RISK[r][1]);
const TIER = {
  1: { name: 'Priority 1 - act now', bg: '#b42318' },
  2: { name: 'Priority 2 - chase this week', bg: '#b54708' },
  3: { name: 'Priority 3 - monitor', bg: '#475467' }
};

let h = '<div style="' + F + 'max-width:1000px;color:#101828;">';
h += '<h1 style="' + F + 'font-size:20px;margin:0 0 4px;">' + (fullDay ? 'Overdue invoices and bills: full list' : 'New overdue invoices and bills') + '</h1>';
h += '<div style="' + F + 'font-size:13px;color:#475467;margin:0 0 16px;">' + esc($now.setZone('Europe/London').toFormat('cccc dd LLLL yyyy')) + ' | all five Xero organisations</div>';

// Overview
const card = (label, big, small, color) => '<td style="width:33%;padding:12px 14px;border:1px solid #e4e7ec;background:#fcfcfd;vertical-align:top;"><div style="font-size:12px;color:#475467;">' + esc(label) + '</div><div style="font-size:22px;font-weight:bold;color:' + color + ';margin:4px 0;">' + esc(big) + '</div><div style="font-size:12px;color:#475467;">' + esc(small) + '</div></td>';
h += '<table style="' + TABLE + '"><tr>' +
  card('Owed to us (customer invoices)', gbp(sum(rec, 'amountDueRaw')), rec.length + ' overdue | est. value at risk ' + gbp(sum(rec, 'valueAtRisk')), '#067647') +
  card('We owe (supplier bills)', gbp(sum(pay, 'amountDueRaw')), pay.length + ' overdue', '#b42318') +
  card(fullDay ? 'Needs action now' : 'New or worse since last report', String(shown.length) + ' item(s)', fresh.filter(r => r.change === 'new').length + ' new, ' + fresh.filter(r => r.change === 'escalated').length + ' more urgent, ' + fresh.filter(r => r.change === 'reminder').length + ' still unpaid | ' + all.length + ' overdue in total', '#101828') +
  '</tr></table>';

if (fullDay) {
// Matrix
h += '<h2 style="' + H2 + '">Value x risk matrix - customer invoices (count / amount)</h2>';
h += '<table style="' + TABLE + '"><tr><th style="' + TH + '">Value \\ Risk</th><th style="' + TH + '">High risk</th><th style="' + TH + '">Medium risk</th><th style="' + TH + '">Low risk</th></tr>';
for (const v of ['High', 'Medium', 'Low']) {
  h += '<tr><td style="' + TD + 'font-weight:bold;">' + v + ' value</td>';
  for (const rk of ['High', 'Medium', 'Low']) {
    const s = rec.filter(r => r.valueBand === v && r.riskProfile === rk);
    h += '<td style="' + TD + (s.length ? 'background:' + RISK[rk][0] + ';' : 'color:#98a2b3;') + '">' + s.length + ' / ' + esc(gbp(sum(s, 'amountDueRaw'))) + '</td>';
  }
  h += '</tr>';
}
h += '</table>';

// Ageing + top customers
const ageRows = AGE_BUCKETS.map(b => ({ b, s: rec.filter(r => r.ageBucket === b.label) })).filter(x => x.s.length);
if (ageRows.length) {
  h += '<h2 style="' + H2 + '">Ageing - customer invoices</h2><table style="' + TABLE + '"><tr><th style="' + TH + '">Age</th><th style="' + TH + '">Items</th><th style="' + TH + 'text-align:right;">Amount</th></tr>';
  for (const x of ageRows) h += '<tr><td style="' + TD + '">' + esc(x.b.label) + '</td><td style="' + TD + '">' + x.s.length + '</td><td style="' + TDR + '">' + esc(gbp(sum(x.s, 'amountDueRaw'))) + '</td></tr>';
  h += '</table>';
}
const topCustomers = Object.values(byContact).filter(c => c.type === 'ACCREC').sort((a, b) => b.total - a.total).slice(0, 5);
if (topCustomers.length) {
  h += '<h2 style="' + H2 + '">Top customers by amount owed</h2><table style="' + TABLE + '"><tr><th style="' + TH + '">#</th><th style="' + TH + '">Customer</th><th style="' + TH + '">Company</th><th style="' + TH + '">Invoices</th><th style="' + TH + 'text-align:right;">Total owed</th></tr>';
  topCustomers.forEach((c, n) => { h += '<tr><td style="' + TD + '">' + (n + 1) + '</td><td style="' + TD + '">' + esc(c.contact) + '</td><td style="' + TD + '">' + esc(c.company) + '</td><td style="' + TD + '">' + c.count + '</td><td style="' + TDR + '">' + esc(gbp(c.total)) + '</td></tr>'; });
  h += '</table>';
}

}
// Priority tiers
for (const t of [1, 2, 3]) {
  const s = shown.filter(r => r.priority === t);
  if (!s.length && !fullDay) continue;
  h += '<div style="' + F + 'background:' + TIER[t].bg + ';color:#ffffff;padding:8px 12px;margin:28px 0 0;font-size:14px;font-weight:bold;">' + esc(TIER[t].name) + ' <span style="font-weight:normal;">| ' + s.length + ' item(s) | ' + esc(gbp(sum(s, 'amountDueRaw'))) + '</span></div>';
  if (!s.length) { h += '<div style="' + F + 'font-size:13px;color:#475467;padding:10px 12px;border:1px solid #e4e7ec;">Nothing in this tier.</div>'; continue; }
  h += '<table style="' + TABLE + '"><tr>' + ['#', 'Type', 'Company', 'Contact', 'Invoice', 'Amount due', 'Due date', 'Days overdue', 'Value', 'Risk', 'Why / notes'].map((x, i) => '<th style="' + TH + (i === 5 || i === 7 ? 'text-align:right;' : '') + '">' + x + '</th>').join('') + '</tr>';
  s.forEach((r, n) => {
    const owed = r.invoiceTypeCode === 'ACCREC';
    const notes = r.riskReasons.slice();
    if (r.change === 'new') notes.unshift('NEW'); else if (r.change === 'escalated') notes.unshift('MORE URGENT than last report'); else if (r.change === 'reminder') notes.unshift('STILL UNPAID - first reported ' + (r.firstReported || 'earlier'));
    if (owed) notes.push('Est. value at risk ' + gbp(r.valueAtRisk));
    h += '<tr>' +
      '<td style="' + TD + '">' + (n + 1) + '</td>' +
      '<td style="' + TD + '">' + (owed ? pill('Owed to us', '#dcfae6', '#067647') : pill('We owe', '#fee4e2', '#b42318')) + '</td>' +
      '<td style="' + TD + '">' + esc(r.company) + '</td>' +
      '<td style="' + TD + '">' + esc(r.supplier) + '</td>' +
      '<td style="' + TD + 'white-space:nowrap;"><a href="' + esc(r.xeroInvoiceUrl) + '" style="color:#175cd3;text-decoration:none;">' + esc(r.invoiceNumber) + '</a></td>' +
      '<td style="' + TDR + 'font-weight:bold;">' + esc(r.amountDue) + '</td>' +
      '<td style="' + TD + 'white-space:nowrap;">' + esc(r.dueDate) + '</td>' +
      '<td style="' + TDR + '">' + r.overdueDays + '</td>' +
      '<td style="' + TD + '">' + esc(r.valueBand) + '</td>' +
      '<td style="' + TD + '">' + riskPill(r.riskProfile) + '</td>' +
      '<td style="' + TD + 'font-size:12px;color:#475467;">' + (notes.length ? esc(notes.join('; ')) : '-') + '</td></tr>';
  });
  h += '</table>';
}

// How it is categorised
h += '<h2 style="' + H2 + '">How items are categorised</h2>';
h += '<table style="' + TABLE + '">' + [
  ['Value', 'High ' + gbp(VALUE_HIGH) + ' and over | Medium ' + gbp(VALUE_MEDIUM) + ' to ' + gbp(VALUE_HIGH - 0.01) + ' | Low below ' + gbp(VALUE_MEDIUM)],
  ['Risk', 'Based on age, how many items the contact has overdue, their total outstanding, and whether they have part-paid.'],
  ['Priority 1', 'High value with Medium or High risk, or Medium value with High risk.'],
  ['Priority 2', 'Other High value, Medium value with Medium risk, or Low value with High risk.'],
  ['Priority 3', 'Everything else.'],
  ['Value at risk', 'A rough guide (amount x typical loss rate for that age), not an accounting provision.']
].map(r => '<tr><td style="' + TD + 'font-weight:bold;width:140px;">' + esc(r[0]) + '</td><td style="' + TD + '">' + esc(r[1]) + '</td></tr>').join('') + '</table>';
h += '</div>';

const p1 = shown.filter(r => r.priority === 1).length;
const nNew = fresh.filter(r => r.change === 'new').length, nEsc = fresh.filter(r => r.change === 'escalated').length, nRem = fresh.filter(r => r.change === 'reminder').length;
const subject = (fullDay ? 'Overdue full list - ' + all.length + ' item(s)' : 'New overdue - ' + nNew + ' new' + (nEsc ? ', ' + nEsc + ' more urgent' : '') + (nRem ? ', ' + nRem + ' still unpaid' : '')) + ', ' + p1 + ' priority 1 - ' + gbp(sum(shown, 'amountDueRaw')) + ' - ' + $now.setZone('Europe/London').toFormat('dd LLL yyyy');
const body = shown.length + ' item(s) shown, ' + all.length + ' overdue in total: ' + rec.length + ' owed to us (' + gbp(sum(rec, 'amountDueRaw')) + '), ' + pay.length + ' we owe (' + gbp(sum(pay, 'amountDueRaw')) + '). ' + p1 + ' priority 1.';

const to_record = fresh.map(r => ({ invoice_key: r.invoiceKey, invoice_id: r.invoiceId || '', company: r.company, ledger: r.invoiceType, contact: r.supplier, invoice_number: r.invoiceNumber, amount_due: r.amountDueRaw, priority: r.priority, overdue_days: r.overdueDays, reason: r.change, reported_at: new Date().toISOString() }));
return [{ json: { subject, html: h, body, to_record, totalItems: all.length, priority1Count: p1, receivableTotal: sum(rec, 'amountDueRaw'), receivableValueAtRisk: sum(rec, 'valueAtRisk'), payableTotal: sum(pay, 'amountDueRaw'), items: shown } }];

// Writes a human-sounding reminder whose tone escalates with the stage.
// Every item comes from the PMS app (daily plan or "send now"), which has already
// decided the stage, the recipient (internal address in test mode) and any CC.
// Several wordings per stage so customers don't receive identical robotic emails.
const NL = String.fromCharCode(10);

function pick(list, seed) {
  let h = 0;
  for (const ch of String(seed)) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  return list[h % list.length];
}

const out = [];
for (const item of $input.all()) {
  const inv = item.json || {};
  const hello = inv.firstName ? 'Hi ' + inv.firstName + ',' : 'Hello,';
  const ref = 'invoice ' + inv.invoiceNumber + ' for ' + inv.amountDue;
  const due = new Date(inv.dueDate + 'T00:00:00Z').toLocaleDateString('en-GB', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'UTC' });

  const scripts = {
    1: [
      { subject: 'Quick reminder: invoice ' + inv.invoiceNumber, body: [hello, '', 'Just a gentle nudge - our records show ' + ref + ' was due on ' + due + ' and is still open.', '', "It's very possible this has already been sorted or simply slipped through the net, in which case please ignore this note.", '', 'Thanks so much,'] },
      { subject: 'Invoice ' + inv.invoiceNumber + ' - friendly reminder', body: [hello, '', 'Hope all is well. I noticed ' + ref + ' passed its due date on ' + due + '.', '', "If payment is already on its way, thank you! If not, could you pop it through when you get a moment?", '', 'Kind regards,'] }
    ],
    2: [
      { subject: 'Following up on invoice ' + inv.invoiceNumber, body: [hello, '', 'I wanted to follow up on ' + ref + ', which is now ' + inv.overdueDays + ' days overdue (due ' + due + ').', '', 'If there is anything holding it up - a query on the invoice, a missing PO, or anything else - just reply and let me know and I will happily help.', '', 'Many thanks,'] },
      { subject: 'Invoice ' + inv.invoiceNumber + ' is still outstanding', body: [hello, '', 'Checking in on ' + ref + '. It was due on ' + due + ' and we have not yet received payment.', '', 'Could you let me know when we can expect it? If something is not right with the invoice, I would rather hear about it so we can fix it.', '', 'Thanks,'] }
    ],
    3: [
      { subject: 'Action needed: invoice ' + inv.invoiceNumber + ' (' + inv.overdueDays + ' days overdue)', body: [hello, '', 'I am getting in touch again about ' + ref + ', now ' + inv.overdueDays + ' days past its due date of ' + due + '.', '', 'Could you please arrange payment this week, or reply with a date we can expect it? If it would help to talk it through or set up a payment plan, I am very happy to arrange a quick call.', '', 'Best regards,'] },
      { subject: 'Invoice ' + inv.invoiceNumber + ' - please confirm a payment date', body: [hello, '', 'We still have ' + ref + ' showing as unpaid, two weeks past the due date (' + due + ').', '', 'I would really appreciate it if you could confirm when payment will be made. If there is a problem on your side, let me know and we will work something out together.', '', 'Kind regards,'] }
    ],
    4: [
      { subject: 'Final reminder: invoice ' + inv.invoiceNumber + ' is ' + inv.overdueDays + ' days overdue', body: [hello, '', 'Despite our earlier reminders, ' + ref + ' (due ' + due + ') remains unpaid and is now ' + inv.overdueDays + ' days overdue.', '', 'Please arrange payment within the next 7 days. If we do not hear from you, we will need to escalate this internally and review next steps on the account.', '', 'If you are experiencing difficulties, please reply today - we would much rather agree a plan with you than take further action.', '', 'Regards,'] }
    ]
  };


  const script = pick(scripts[inv.wordingStage] || scripts[1], inv.invoiceId);
  const body = script.body.concat([inv.signOffName || 'The Accounts Team', inv.company]).join(NL);
  let subject = script.subject;
  if (inv.testMode) subject = '[TEST - would go to ' + (inv.customerEmail || 'NO EMAIL ON FILE') + '] ' + subject;
  else if (!inv.customerEmail) subject = '[No customer email on file: ' + inv.customer + '] ' + subject;

  out.push({ json: Object.assign({}, inv, { subject, body }) });
}
return out;

// Compares last month's supplier and expense-category spend with the previous 6 months,
// and each new recurring bill with that supplier's usual bill amount.
// ---- Tweak these thresholds to suit the business ----
const BASELINE_MONTHS = 6;        // months of history used as "normal"
const MIN_ACTIVE_MONTHS = 4;      // must be billed in at least this many of those months to count as recurring
const SPEND_RISE_PCT = 25;        // flag monthly spend this % above normal...
const SPEND_RISE_MIN = 100;       // ...and at least this many GBP above normal
const PRICE_RISE_PCT = 15;        // flag a recurring bill this % above the supplier's usual amount...
const PRICE_RISE_MIN = 25;        // ...and at least this many GBP above it
const PRICE_MAX_VARIATION = 0.15; // usual bills must be fairly steady (within ~15%) to count as a fixed recurring charge
const PRICE_LOOKBACK_DAYS = 45;   // check bills dated in the last N days
const HIGH_PCT = 50;              // severity High at this % and...
const HIGH_ABS = 500;             // ...this many GBP above normal

const ORGS = [
  { node: 'Management Bill History', label: 'Hinkley Homes Management' },
  { node: 'Lettings Bill History', label: 'Lettings' },
  { node: 'Stays Bill History', label: 'Hinkley Homes Stays Ltd' },
  { node: 'Hinkley Homes Ltd Bill History', label: 'Hinkley Homes Ltd' },
  { node: 'Holdings Bill History', label: 'Hinkley Homes Holdings' }
];

const now = $now.setZone('Europe/London');
const recentMonth = now.minus({ months: 1 }).toFormat('yyyy-MM');
const baselineMonths = [];
for (let i = 2; i <= BASELINE_MONTHS + 1; i++) baselineMonths.push(now.minus({ months: i }).toFormat('yyyy-MM'));
const priceCutoff = now.minus({ days: PRICE_LOOKBACK_DAYS }).toFormat('yyyy-MM-dd');
const round2 = n => Math.round(n * 100) / 100;

function billDate(b) {
  const s = String(b.DateString || '');
  if (s.length >= 10) return s.slice(0, 10);
  const m = String(b.Date || '').match(/Date\((\d+)/);
  return m ? new Date(parseInt(m[1], 10)).toISOString().slice(0, 10) : '';
}

const suppliers = {};
const categories = {};
function add(map, key, base, ym, amount) {
  if (!map[key]) map[key] = Object.assign({ months: {} }, base);
  map[key].months[ym] = (map[key].months[ym] || 0) + amount;
  return map[key];
}

let billsSeen = 0;
for (const o of ORGS) {
  const bills = [];
  for (const it of $(o.node).all()) {
    const j = it.json || {};
    if (Array.isArray(j.Invoices)) bills.push(...j.Invoices); else if (j.Type) bills.push(j);
  }
  for (const b of bills) {
    if (b.Type !== 'ACCPAY') continue;
    if (b.Status !== 'AUTHORISED' && b.Status !== 'PAID') continue;
    const d = billDate(b);
    if (!d) continue;
    billsSeen++;
    const ym = d.slice(0, 7);
    const name = b.Contact && b.Contact.Name ? b.Contact.Name : 'Unknown supplier';
    const amount = parseFloat(b.SubTotal != null ? b.SubTotal : (b.Total || 0)) || 0;
    const sup = add(suppliers, o.label + '|' + name, { company: o.label, name, bills: [] }, ym, amount);
    sup.bills.push({ id: b.InvoiceID, number: b.InvoiceNumber || b.Reference || '', date: d, amount });
    for (const li of (Array.isArray(b.LineItems) ? b.LineItems : [])) {
      const code = li.AccountCode || 'Uncoded';
      const lineAmt = parseFloat(li.LineAmount != null ? li.LineAmount : ((li.Quantity || 0) * (li.UnitAmount || 0))) || 0;
      const cat = add(categories, o.label + '|' + code, { company: o.label, name: 'Account ' + code, descriptions: {} }, ym, lineAmt);
      const desc = String(li.Description || '').split(String.fromCharCode(10))[0].slice(0, 40);
      if (desc) cat.descriptions[desc] = (cat.descriptions[desc] || 0) + 1;
    }
  }
}

const flags = [];
function severity(pct, inc) { return pct >= HIGH_PCT && inc >= HIGH_ABS ? 'High' : 'Medium'; }

function checkSpend(map, flagType) {
  for (const e of Object.values(map)) {
    const vals = baselineMonths.map(m => e.months[m] || 0);
    const active = vals.filter(v => v > 0).length;
    if (active < MIN_ACTIVE_MONTHS) continue; // not a recurring cost
    const baseline = vals.reduce((t, v) => t + v, 0) / BASELINE_MONTHS;
    const recent = e.months[recentMonth] || 0;
    const inc = recent - baseline;
    if (baseline <= 0) continue;
    const pct = inc / baseline * 100;
    if (pct < SPEND_RISE_PCT || inc < SPEND_RISE_MIN) continue;
    let label = e.name;
    if (e.descriptions) {
      const top = Object.entries(e.descriptions).sort((a, b) => b[1] - a[1])[0];
      if (top) label += ' (e.g. "' + top[0] + '")';
    }
    flags.push({
      flagKey: recentMonth + '|' + e.company + '|' + flagType + '|' + e.name,
      period: recentMonth, company: e.company, flagType, subjectName: label,
      recentAmount: round2(recent), baselineAmount: round2(baseline), increaseAmount: round2(inc), increasePct: Math.round(pct),
      severity: severity(pct, inc),
      detail: recentMonth + ' spend vs average of ' + baselineMonths[baselineMonths.length - 1] + ' to ' + baselineMonths[0] + ' (billed in ' + active + ' of ' + BASELINE_MONTHS + ' months)',
      link: ''
    });
  }
}
checkSpend(suppliers, 'Supplier spend');
checkSpend(categories, 'Expense category');

// Recurring bill price rises: a new bill noticeably above a supplier's steady usual amount
for (const e of Object.values(suppliers)) {
  const bills = e.bills.filter(x => x.amount > 0).sort((a, b) => a.date < b.date ? -1 : 1);
  for (let i = 0; i < bills.length; i++) {
    const latest = bills[i];
    if (latest.date < priceCutoff) continue;
    const prior = bills.slice(0, i).slice(-6);
    if (prior.length < 3) continue;
    const sorted = prior.map(x => x.amount).sort((a, b) => a - b);
    const median = sorted[Math.floor(sorted.length / 2)];
    if (!(median > 0)) continue;
    if ((sorted[sorted.length - 1] - sorted[0]) / median > PRICE_MAX_VARIATION) continue; // not a steady charge
    const inc = latest.amount - median;
    const pct = inc / median * 100;
    if (pct < PRICE_RISE_PCT || inc < PRICE_RISE_MIN) continue;
    flags.push({
      flagKey: 'price|' + latest.id,
      period: latest.date.slice(0, 7), company: e.company, flagType: 'Recurring bill price', subjectName: e.name + (latest.number ? ' - ' + latest.number : ''),
      recentAmount: round2(latest.amount), baselineAmount: round2(median), increaseAmount: round2(inc), increasePct: Math.round(pct),
      severity: severity(pct, inc),
      detail: 'Bill dated ' + latest.date + ' vs usual amount over the previous ' + prior.length + ' bills',
      link: 'https://go.xero.com/AccountsPayable/View.aspx?invoiceID=' + latest.id
    });
  }
}

flags.sort((a, b) => (a.severity === b.severity ? 0 : a.severity === 'High' ? -1 : 1) || b.increaseAmount - a.increaseAmount);
return flags.map(f => ({ json: Object.assign(f, { billsAnalysed: billsSeen }) }));

// One email listing every newly detected cost increase, biggest first
const NL = String.fromCharCode(10);
const gbp = n => '£' + Number(n || 0).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const flags = $input.all().map(i => i.json).filter(j => j && j.flagKey);
const total = flags.reduce((t, f) => t + (f.increaseAmount || 0), 0);
const sections = [['Supplier spend', 'SUPPLIERS SPENDING MORE THAN USUAL (last month vs 6-month average)'], ['Expense category', 'EXPENSE CATEGORIES ABOVE NORMAL (by account code)'], ['Recurring bill price', 'RECURRING BILLS PRICED ABOVE THE USUAL AMOUNT']];
const out = [];
out.push(flags.length + ' new unusual cost increase(s) detected across your Xero organisations, together ' + gbp(total) + ' above normal.');
out.push('');
for (const [type, title] of sections) {
  const s = flags.filter(f => f.flagType === type);
  if (!s.length) continue;
  out.push('==== ' + title + ' ====');
  s.forEach((f, n) => {
    out.push((n + 1) + '. [' + f.severity + '] ' + f.company + ' | ' + f.subjectName);
    out.push('   ' + gbp(f.recentAmount) + ' vs normal ' + gbp(f.baselineAmount) + ' -> +' + gbp(f.increaseAmount) + ' (+' + f.increasePct + '%)');
    out.push('   ' + f.detail + (f.link ? NL + '   ' + f.link : ''));
  });
  out.push('');
}
out.push('How this works: only recurring costs are checked (billed in most of the last 6 months, or a steady repeating bill). Amounts are net of VAT where Xero provides it. Each increase is reported once.');
const subject = 'Cost increase alert - ' + flags.length + ' unusual rise(s), ' + gbp(total) + ' above normal - ' + $now.setZone('Europe/London').toFormat('dd LLL yyyy');
return [{ json: { subject, body: out.join(NL), flags } }];

// Housekeeping: forget invoices that are no longer overdue (paid, credited, voided, deleted)
// so the "Overdue Reported" table stays small. If one ever goes overdue again it is reported as new.
const MAX_PRUNE_SHARE = 0.5; // safety: if more than this share of the table would be removed (and more than 5 rows), do nothing - probably a failed Xero call
const current = new Set();
let fetched = 0;
for (const i of $input.all()) {
  const j = i.json || {};
  if (!j.company || !(j.amountDueRaw > 0)) continue;
  fetched++;
  current.add(j.company + '|' + (j.invoiceId || j.invoiceNumber));
}
let rows = [];
try { rows = $('Get reported overdue').all().map(r => r.json || {}).filter(j => j.invoice_key); } catch (e) { return []; }
const keys = [...new Set(rows.map(j => j.invoice_key))];
const stale = keys.filter(k => !current.has(k));
if (!stale.length) return [];
if (stale.length > 5 && stale.length / keys.length > MAX_PRUNE_SHARE) return []; // looks like a failed fetch
return stale.map(k => ({ json: { invoice_key: k } }));

// One item per reminder the PMS says is due today (none when switched off).
const plan = $input.first().json || {};
return (Array.isArray(plan.items) ? plan.items : []).map(item => ({ json: item }));

// Items sent by the PMS app ({ items: [...] }).
const body = $input.first().json.body || {};
return (Array.isArray(body.items) ? body.items : []).map(item => ({ json: item }));

// Result for the PMS (logged against the invoice).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const response = items[i].json || {};
  const src = $('Request items').itemMatching(i).json;
  const code = Number(response.statusCode || 0);
  const ok = code >= 200 && code < 300;
  out.push({ json: {
    action: src.action, kind: 'xero_resend', tenantId: src.tenantId, invoiceId: src.invoiceId,
    invoiceNumber: src.invoiceNumber, customer: src.customer, stage: null, testMode: false,
    sentTo: null, subject: null, status: ok ? 'sent' : 'failed',
    detail: ok ? null : ('Xero returned HTTP ' + (code || '?') + ': ' + JSON.stringify(response.body || response.error || '').slice(0, 300)), requestedBy: src.requestedBy || null
  } });
}
return out;

// Result for the PMS (logged against the invoice).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const response = items[i].json || {};
  const src = $('Request items').itemMatching(i).json;
  const code = Number(response.statusCode || 0);
  const ok = code >= 200 && code < 300;
  out.push({ json: {
    action: src.action, kind: 'xero_note', tenantId: src.tenantId, invoiceId: src.invoiceId,
    invoiceNumber: src.invoiceNumber, customer: src.customer, stage: null, testMode: false,
    sentTo: null, subject: null, status: ok ? 'sent' : 'failed',
