  } });
}
return out;

// Result for the PMS after each reminder email (sent, or failed with the reason).
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const sent = items[i].json || {};
  const w = $('Write Reminder Email').itemMatching(i).json;
  const failed = Boolean(sent.error);
  out.push({ json: {
    action: 'reminder', kind: w.kind, tenantId: w.tenantId, invoiceId: w.invoiceId,
    invoiceNumber: w.invoiceNumber, customer: w.customer, stage: w.stage, testMode: w.testMode === true,
    sentTo: w.sendTo, subject: w.subject, status: failed ? 'failed' : 'sent',
    detail: failed ? String(sent.error && sent.error.message ? sent.error.message : sent.error).slice(0, 500) : null,
    requestedBy: w.requestedBy || null,
    xeroHistoryNotes: w.xeroHistoryNotes === true,
    note: 'Payment reminder (stage ' + w.stage + ') emailed to ' + w.sendTo + ' by Hinkley Homes PMS' + (w.requestedBy ? ' (sent by ' + w.requestedBy + ').' : ' (automatic).')
  } });
}
return out;
